function apply(before,edits,id){edits.sort((a,b)=>a.start-b.start||a.end-b.end);for(let i=1;i<edits.length;i++)assert(edits[i].start>=edits[i-1].end,'overlapping edits');let after=before,delta=0;for(const e of edits){assert.equal(before.slice(e.start,e.end),e.before);e.afterStart=e.start+delta;e.afterEnd=e.afterStart+e.after.length;delta+=e.after.length-e.before.length}for(const e of [...edits].reverse())after=after.slice(0,e.start)+e.after+after.slice(e.end);let inverse=after;for(const e of [...edits].reverse())inverse=inverse.slice(0,e.afterStart)+e.before+inverse.slice(e.afterEnd);assert.equal(inverse,before);parse(after);write(id+'-patches.json',edits);return{after,proof:{beforeSha256:sha(before),sha256:sha(after),patches:edits.length,exactInverse:true,allNonpatchBytesUnchanged:true}}}
