function uiInsertion(code,ast,root=ast){const names=['Ls','Ds'];for(const n of names)assert.equal(nodes(root,x=>ts.isFunctionDeclaration(x)&&x.name?.text===n).length,1,'existing authorized hook '+n);const live=nodes(root,n=>ts.isVariableDeclaration(n)&&n.name.getText(ast)==='__live');assert.equal(live.length,1);const keys=new Set(live[0].initializer.properties.map(n=>n.name.text));for(const n of ['ChatPage','BusinessContentFrame','formatBeijingDateTime','useLocation','useSearch','React','jsx'])assert(keys.has(n),'existing bridge '+n);return `\nlet __d51_rx_ui_instance;function __d51_rx_ui_get(){if(!__d51_rx_ui_instance){const __rxLive={React:__live.React,jsx:__live.jsx,ChatPage:__live.ChatPage,BusinessContentFrame:__live.BusinessContentFrame,formatBeijingDateTime:__live.formatBeijingDateTime,useLocation:__live.useLocation,useSearch:__live.useSearch,useInquiryReception:Ls,useInquiryReceptionNotice:Ds};${code}\n__d51_rx_ui_instance=__RX_UI_EXPORTS;}return __d51_rx_ui_instance;}\nfunction fr(props){return __d51_rx_ui_get().InquiryReception(props)}\n`}
function specs(s){const a=parse(s);return [...new Set(nodes(a,n=>(ts.isImportDeclaration(n)||ts.isExportDeclaration(n))&&n.moduleSpecifier||ts.isCallExpression(n)&&n.expression.kind===ts.SyntaxKind.ImportKeyword).map(n=>n.moduleSpecifier??n.arguments[0]).map(n=>{assert(ts.isStringLiteral(n),'nonliteral dynamic import must be explicitly audited');return n.text}))]}
function resolve(spec,from,map){const key=spec.startsWith('.')||spec.startsWith('/')?new URL(spec,'https://admin.51dianzi.com'+from).pathname:spec;const tables=Object.keys(map.scopes??{}).filter(s=>from.startsWith(s)).sort((a,b)=>b.length-a.length).map(s=>map.scopes[s]);tables.push(map.imports??{});for(const t of tables){if(Object.hasOwn(t,key))return t[key];if(Object.hasOwn(t,spec))return t[spec];}return key}
function finishHTML(cssUrl){const before=read(BASE+'/index-before.html'),match=before.match(/<script[^>]*type="importmap"[^>]*>([\s\S]*?)<\/script>/);assert(match);const oldText=match[1],old=JSON.parse(oldText);let text=oldText;const changes=[];for(const [from,to]of Object.entries(relocations)){let hits=0;const pattern=new RegExp('(:\\s*)'+JSON.stringify(from).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'g');text=text.replace(pattern,(_,prefix)=>{hits++;return prefix+JSON.stringify(to)});changes.push({from,to,hits})}let map=JSON.parse(text);const extras=[];for(const [from,to]of Object.entries(relocations)){if(!Object.hasOwn(map.imports,from))extras.push(JSON.stringify(from)+':'+JSON.stringify(to));else assert.equal(map.imports[from],to)}
 if(extras.length){const a=ts.parseJsonText('map.json',text),obj=a.statements[0].expression.properties.find(p=>p.name.text==='imports').initializer;text=text.slice(0,obj.end-1)+','+extras.join(',')+text.slice(obj.end-1);map=JSON.parse(text)}
 const clones=[];for(const [from,to]of Object.entries(relocations)){const scopes=Object.keys(map.scopes??{}).filter(s=>from.startsWith(s)&&!to.startsWith(s)).sort((a,b)=>b.length-a.length);if(scopes.length){assert(!map.scopes[to]);clones.push({oldScope:scopes[0],newScope:to,table:map.scopes[scopes[0]]})}}
 if(clones.length){const a=ts.parseJsonText('map.json',text),obj=a.statements[0].expression.properties.find(p=>p.name.text==='scopes').initializer;text=text.slice(0,obj.end-1)+','+clones.map(x=>JSON.stringify(x.newScope)+':'+JSON.stringify(x.table)).join(',')+text.slice(obj.end-1);map=JSON.parse(text)}
 for(const [k,v]of Object.entries(old.imports))assert.equal(map.imports[k],relocations[v]??v);for(const [scope,table]of Object.entries(old.scopes??{})){assert.deepEqual(Object.keys(map.scopes[scope]),Object.keys(table));for(const [k,v]of Object.entries(table))assert.equal(map.scopes[scope][k],relocations[v]??v)}const dependencies=new Set(),checks=[];for(const [from,to]of Object.entries(relocations)){const oldSpecs=specs(read(BASE+from)),newSpecs=specs(read(OUT+to));assert.deepEqual(newSpecs,oldSpecs);for(const spec of oldSpecs){const b=resolve(spec,from,old),a=resolve(spec,to,map);assert.equal(a,relocations[b]??b,'unchanged effective dependency '+spec);dependencies.add(a);checks.push({from:to,spec,resolved:a})}}
 const tag=`<link rel="stylesheet" href="${cssUrl}" data-reception-front-design="20261113">\n`;const start=match.index+match[0].indexOf(oldText);let after=before.slice(0,start)+text+before.slice(start+oldText.length);after=after.replace('</head>',tag+'</head>');assert.equal(after.replace(text,oldText).replace(tag,''),before);write('index.html',after);records.unshift({relative:'index.html',sha256:sha(after)});write('html-build-proof.json',{beforeSha256:sha(before),sha256:sha(after),exactInverse:true,preservedOldImportsAndScopes:true,clonedScopes:clones.map(({oldScope,newScope})=>({oldScope,newScope})),changes,relocations,onlyNewStylesheet:cssUrl});write('dependency-resolution-proof.json',{status:'PASS',checks,preservedOldScopes:true});write('static-dependencies.json',[...dependencies]);write('files.json',records)}
async function main(){const ui=await compileUI(),urls=JSON.parse(read(BASE+'/selected-urls.json'));for(const [idx,url]of urls.filter(x=>x.includes('BusinessWorkbench')).entries()){const before=read(BASE+url),a=parse(before),get=nodes(a,n=>ts.isFunctionDeclaration(n)&&n.name?.text==='__d51_ir_w_get');assert.equal(get.length,1);const existingFr=nodes(get[0],n=>ts.isFunctionDeclaration(n)&&n.name?.text==='fr');assert.equal(existingFr.length,1);const stmts=existingFr[0].parent.statements,first=stmts.findIndex(n=>ts.isVariableStatement(n)&&n.declarationList.declarations.some(d=>d.name.getText(a)==='__d51_rx_ui_instance')),last=stmts.findIndex(n=>ts.isFunctionDeclaration(n)&&n.name?.text==='fr');assert(first>=0&&last===first+2,'only original UI capsule statements');assert(ts.isFunctionDeclaration(stmts[first+1])&&stmts[first+1].name.text==='__d51_rx_ui_get');const oldChat=stmts.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text==='ps');assert(oldChat);const edits=[{start:stmts[first].getStart(a),end:stmts[last].end,before:before.slice(stmts[first].getStart(a),stmts[last].end),after:uiInsertion(ui,a,get[0]),reason:'front-chat-three-column-UI-only'}];const out=apply(before,edits,'workbench-'+idx),newAst=parse(out.after),newGet=nodes(newAst,n=>ts.isFunctionDeclaration(n)&&n.name?.text==='__d51_ir_w_get')[0],newFr=nodes(newGet,n=>ts.isFunctionDeclaration(n)&&n.name?.text==='fr')[0],newChat=newFr.parent.statements.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text==='ps');assert.equal(oldChat.getText(a),newChat.getText(newAst),'all prior chat changes byte-identical');const oldHelpers=a.statements.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text==='__d51_rx_chat_helpers_get'),newHelpers=newAst.statements.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text==='__d51_rx_chat_helpers_get');assert.equal(oldHelpers.getText(a),newHelpers.getText(newAst),'all draft/phrase/sticker helpers preserved');const oldInstance=a.statements.find(n=>ts.isVariableStatement(n)&&n.declarationList.declarations.some(d=>d.name.getText(a)==='__d51_rx_chat_helpers_instance')),newInstance=newAst.statements.find(n=>ts.isVariableStatement(n)&&n.declarationList.declarations.some(d=>d.name.getText(newAst)==='__d51_rx_chat_helpers_instance'));assert(oldInstance&&newInstance);assert.equal(oldInstance.getText(a),newInstance.getText(newAst),'helper initialization unchanged');const newUrl=asset('BusinessWorkbenchPage-front-chat-design-'+idx,out.after);relocations[url]=newUrl;write('workbench-'+idx+'-build-proof.json',{...out.proof,url:newUrl,beforeUrl:url,uiSourceSha256:sha(read(REPO+'/client/src/business/InquiryReception.tsx')),chatFunctionSha256:sha(oldChat.getText(a)),chatHelpersSha256:sha(oldInstance.getText(a)+'\n'+oldHelpers.getText(a)),allPriorChatCodeUnchanged:true})}const css=(await esbuild.transform(read(REPO+'/client/src/business/InquiryReception.css'),{loader:'css',minify:true})).code,cssUrl=asset('inquiry-reception-front-chat-design',css,'css');finishHTML(cssUrl);console.log(JSON.stringify({status:'BUILT',files:records.length,relocations,cssUrl}))}
